// File System Access API types
declare global {
  interface Window {
    showDirectoryPicker(options?: {
      mode?: "read" | "readwrite";
    }): Promise<FileSystemDirectoryHandle>;
  }

  interface FileSystemDirectoryHandle {
    name: string;
    queryPermission(descriptor?: {
      mode?: "read" | "readwrite";
    }): Promise<PermissionState>;
    requestPermission(descriptor?: {
      mode?: "read" | "readwrite";
    }): Promise<PermissionState>;
  }
}

interface MarbleMediaFile {
  id: string;
  file: File;
  media_asset_id: string;
  metadata: Record<string, unknown>;
  kind: "image" | "video";
  extension: string;
  file_name: string;
  file_src: string;
  azimuth: number;
}

interface MarbleModelInfo {
  id: string;
  name: string | "";
  image: string | "";
  status: "pending" | "running" | "completed" | "failed";
  srcurl: string | "";
  textPrompt: string | "";
  created_at: string | "";
  updated_at: string | "";
}

