  initExistViewDialog() {
    const cancelBtn = document.getElementById("visionCancelBtn");
    const confirmBtn = document.getElementById("visionConfirmBtn");
    const optionItems = document.querySelectorAll(".vision-option-item");
    let selectedValue: ViewWindow = "left" as ViewWindow;

    // 重置选择
    optionItems.forEach((item) => {
      const el = item as HTMLElement;
      if (el.dataset.value === selectedValue) {
        el.classList.add("vision-option-selected");
      } else {
        el.classList.remove("vision-option-selected");
      }
    });

    // 选择选项
    optionItems.forEach((item) => {
      const el = item as HTMLElement;
      el.addEventListener("click", () => {
        selectedValue =
          (el.dataset.value as ViewWindow) || ("left" as ViewWindow);
        optionItems.forEach((opt) =>
          (opt as HTMLElement).classList.remove("vision-option-selected")
        );
        el.classList.add("vision-option-selected");
      });
    });

    // 关闭模态框
    const modal = this.exitViewModalDom;
    const closeModal = () => {
      if (modal) {
        modal.classList.remove("vision-modal-show");
      }
    };

    // 取消按钮
    if (cancelBtn) {
      cancelBtn.addEventListener("click", closeModal);
    }

    // 确认按钮
    if (confirmBtn) {
      confirmBtn.addEventListener("click", () => {
        console.log("选择的视窗:", selectedValue);
        if (
          globalTools.mainViewTools &&
          typeof globalTools.mainViewTools.removePanel === "function"
        ) {
          globalTools.mainViewTools.removePanel(selectedValue !== "left");
        }
        // 执行确认关闭视窗操作
        globalTools?.toolbarNavTools?.setSceneWindowSingle(true);
        closeModal();
        // 这里可以添加确认后的逻辑
      });
    }

    // 点击遮罩层关闭
    if (modal) {
      modal.addEventListener("click", (e) => {
        if (e.target === modal) {
          closeModal();
        }
      });
    }
  }

